def _get_cleaned_column_resolvers(self) -> dict[Hashable, Series]:
    """
    Return the special character free column resolvers of a DataFrame.

    Column names with special characters are 'cleaned up' so that they can
    be referred to by backtick quoting.
    Used in :meth:`DataFrame.eval`.
    """
    def pandas_dtype(dtype) -> 'Dtype':
        """
        Convert input into a pandas only dtype object or a numpy dtype object.

        Parameters
        ----------
        dtype : object to be converted

        Returns
        -------
        np.dtype or a pandas dtype

        Raises
        ------
        TypeError if not a dtype

        Examples
        --------
        >>> pd.api.types.pandas_dtype(int)
        dtype('int64')
        """
        import numpy as np
        from pandas.core.arrays.string_ import StringDtype
        import warnings
        from pandas.core.dtypes.common import registry

        # short-circuit
        if isinstance(dtype, np.ndarray):
            return dtype.dtype
        elif isinstance(dtype, np.dtype):
            return dtype

        # builtin aliases
        if dtype is str and pd.api.types.is_string_dtype(dtype):
            return StringDtype(na_value=np.nan)

        # try a numpy dtype
        try:
            return np.dtype(dtype)
        except SyntaxError as err:
            raise TypeError(f"data type '{dtype}' not understood") from err

        raise TypeError(f"dtype '{dtype}' not understood")

    from pandas.core.computation.parsing import clean_column_name
    from pandas.core.series import Series
    import pandas as pd

    if isinstance(self, pd.core.series.Series):
        return {clean_column_name(self.name): self}

    dtypes = self.dtypes
    return {
        clean_column_name(k): Series(
            v, copy=False, index=self.index, name=k, dtype=pandas_dtype(dtypes[k])
        ).__finalize__(self)
        for k, v in zip(self.columns, self._iter_column_arrays())
        if not isinstance(k, int)
    }
